package clean.app

import android.content.ComponentName
import android.content.Context
import android.content.pm.PackageManager
import clean.app.ui.theme.ACCENTS

/**
 * The launcher icon is one `activity-alias` of MainActivity per tile and accent (generated by `tools/icons/make_icons.py` into the
 * manifest); exactly one is enabled. The tile is the icon part of the look, the accent the icon accent. A key is `black_blue`.
 */
object IconAliases {
    /** The alias the manifest enables: today's icon, a black tile with a blue ring. */
    const val DEFAULT = "black_blue"
    val TILES = listOf("black", "dark", "white", "paper", "linen")
    val ACCENT_NAMES = ACCENTS.keys.toList() + "Ink"

    fun key(tile: String, accent: String) = "${tile}_${accent.lowercase()}"

    /** The alias's class name, as the manifest spells it: `clean.app.IconBlackBlue`. */
    private fun component(context: Context, key: String): ComponentName {
        val (tile, accent) = key.split('_')
        return ComponentName(context.packageName, "clean.app.Icon${tile.replaceFirstChar { it.uppercase() }}${accent.replaceFirstChar { it.uppercase() }}")
    }

    /** Enables the alias for [wanted] first, then disables the one that was applied before ([applied]) and the manifest's own, so the launcher never has none. */
    fun switch(context: Context, wanted: String, applied: String?) {
        val packages = context.packageManager
        packages.setComponentEnabledSetting(component(context, wanted), PackageManager.COMPONENT_ENABLED_STATE_ENABLED, PackageManager.DONT_KILL_APP)
        for (old in setOfNotNull(applied, DEFAULT) - wanted) {
            packages.setComponentEnabledSetting(component(context, old), PackageManager.COMPONENT_ENABLED_STATE_DISABLED, PackageManager.DONT_KILL_APP)
        }
    }
}
